package pie.ilikepiefoo.compat.jade.builder.callback;import net.minecraft.server.level.ServerLevel;import net.minecraft.server.level.ServerPlayer;import pie.ilikepiefoo.compat.jade.builder.ViewGroupBuilder;import snownee.jade.api.Accessor;import java.util.ArrayList;import java.util.List;import java.util.function.Consumer;public class GetServerGroupsCallbackJS<IN, OUT> {    public final Accessor<?> accessor;    public final ServerPlayer player;    public final ServerLevel world;    public final IN target;    public final boolean showDetails;    private final List<ViewGroupBuilder<OUT>> groups;    @SuppressWarnings("unchecked")    public GetServerGroupsCallbackJS(Accessor<?> accessor) {        this.accessor = accessor;        this.player = accessor.getPlayer() instanceof ServerPlayer serverPlayer ? serverPlayer : null;        this.world = accessor.getLevel() instanceof ServerLevel serverLevel ? serverLevel : null;        this.target = (IN) accessor.getTarget();        this.showDetails = accessor.showDetails();        this.groups = new ArrayList<>();    }    public Accessor<?> getAccessor() {        return this.accessor;    }    public ServerPlayer getPlayer() {        return this.player;    }    public ServerLevel getWorld() {        return this.world;    }    public ServerLevel getLevel() {        return this.world;    }    public IN getTarget() {        return this.target;    }    public boolean showDetails() {        return this.showDetails;    }    public List<ViewGroupBuilder<OUT>> getGroups() {        return this.groups;    }    public GetServerGroupsCallbackJS<IN, OUT> addGroup(ViewGroupBuilder<OUT> group) {        this.groups.add(group);        return this;    }    public GetServerGroupsCallbackJS<IN, OUT> addGroup(List<OUT> group) {        this.groups.add(new ViewGroupBuilder<OUT>().addAll(group));        return this;    }    public GetServerGroupsCallbackJS<IN, OUT> addGroup(Consumer<ViewGroupBuilder<OUT>> groupBuilderConsumer) {        ViewGroupBuilder<OUT> group = new ViewGroupBuilder<>();        groupBuilderConsumer.accept(group);        this.groups.add(group);        return this;    }    public GetServerGroupsCallbackJS<IN, OUT> addGroups(List<ViewGroupBuilder<OUT>> groups) {        this.groups.addAll(groups);        return this;    }    public GetServerGroupsCallbackJS<IN, OUT> clearGroups() {        this.groups.clear();        return this;    }}